    @Test
    public void testVisit_FunctionScopeSpecialCase() {
        String oldName = "obj.prop";
        when(node.getType()).thenReturn(Token.NAME);
        when(node.getString()).thenReturn(oldName);
        when(scope.getVar(oldName)).thenReturn(var);
        when(var.isGlobal()).thenReturn(false);
        when(var.scope).thenReturn(scope);
        when(var.getParentNode()).thenReturn(parent);
        when(var.getNameNode()).thenReturn(node);

        when(parent.getType()).thenReturn(Token.FUNCTION);
        when(scope.getRootNode()).thenReturn(parent);
        when(scope.isDeclared(anyString(), anyBoolean())).thenReturn(false);

        inverter.visit(t, node, parent);

